def solve():
    input = sys.stdin.readline
    for _ in range(int(input())):
        pin = input().strip()
        dist = {(i,j): abs(ord(pin[i]) - ord(pin[j])) + abs(i - j) for i in range(4) for j in range(4)}
        q, ans = [(0, 1)], 0
        while q:
            d, cur = heapq.heappop(q)
            if cur == 4:
                ans = d
                break
            for i in range(4):
                if i!= cur:
                    heapq.heappush(q, (d + dist[(cur-1)%4+1][i] + dist[(i+1)%4+1][cur-1], i+1))
                    heapq.heappush(q, (d + dist[cur-1][(i+1)%4+1] + dist[i%4+1][cur-1], i+1))
        print(ans)

