    a = list(map(int, input().split()))
    prefix_sum = [0]
    for i in range(n):
        prefix_sum.append(prefix_sum[-1] + a[i])
    a = [-sys.maxsize] + a
    for i in range(1, n + 1):
        a[i] = max(a[i], a[i - 1])
    suffix_sum = [0]
    for i in range(n, 0, -1):
        suffix_sum.append(suffix_sum[-1] + a[i])
    suffix_sum.reverse()
    dp = [0] * (k + 1)
    for i in range(1, k + 1):
        max_prefix = -sys.maxsize
        for j in range(i):
            max_prefix = max(max_prefix, suffix_sum[j + 1])
        dp[i] = sys.maxsize
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + (prefix_sum[i] - prefix_sum[j]) - max_prefix)
    return dp[-1]

