def solve():
    n = int(input())
    s = input().strip()

    graph = defaultdict(list)
    for i in range(n):
        for j in range(i + 1, n):
            if s[i]!= s[j]:
                graph[s[i]].append(s[j])
                graph[s[j]].append(s[i])

    def dfs(c, prev, color):
        for nc in graph[c]:
            if color[nc] == -1:
                color[nc] = 1 - color[c]
                dfs(nc, c, color)
            elif color[nc]!= 1 - color[c]:
                return False
        return True

    color = [-1] * 26
    for i in range(n):
        if color[ord(s[i]) - ord('a')] == -1:
            color[ord(s[i]) - ord('a')] = 0
            if not dfs(s[i], -1, color):
                return False

    return "YES"

