def solve():
    n = int(input())
    s = input()
    heap = []
    for i in range(n):
        heappush(heap, (ord(s[i]), i, s[i]))
    while len(heap) > 1:
        a, _, _ = heappop(heap)
        b, _, _ = heappop(heap)
        if a < b:
            heappush(heap, (a, 0, s[0]))
            s = s[1:]
            break
        else:
            heappush(heap, (b, 0, s[0]))
            s = s[1:]
    return ''.join([x[2] for x in sorted(heap)])

